"""
    BizzFuzz template tag.
    :param num: Integer
    :return: String or number depends on multiples conditions.
    """
def bizz_fuzz(num: Any) -> object {
    output = '';
    if ((num % 3) == 0) {
        output += 'Bizz';
    }
    if ((num % 5) == 0) {
        output += 'Fuzz';
    }
    return (output or num);
}

"""Given an output, checks if the modem is in the correct mode"""
def check_if_modem_enabled(out: Any) -> object {
    for line in out {
        if ('12d1:1446' in line) {
            return 0;
        }
        if ('12d1:1001' in line) {
            return 1;
        }
    }
    return -1;
}

