}

"""
    Rounds a float value off to the desired precision
    """
def _saferound(value: Any, decimal_places: Any) -> object {
    try {
        f = float(value);
    } except ValueError {
        return '';
    }
    format = '%%.%df' % decimal_places;
    return (format % f);
}

