"""Generate the region_params list in the tiling parameter dict

    Args:
        region_params (dict):
            A dictionary mapping each region-specific parameter to a list of values per fov

    Returns:
        list:
            The complete set of region_params sorted by run
    """
def generate_region_info(region_params: Any) -> object {
    region_params_list = [];
    for i in range(len(region_params['region_start_x'])) {
        region_info = {rp: region_params[rp][i] for rp in region_params};
        region_params_list.append(region_info);
    }
    return region_params_list;
}

"""Give a heuristic evaluation in form of a number
    of how good it would be to make "move" to "game_state". The value is
    higher the better the move, regardless of the player to make it.

    This function give higher values to more central columns.
    """
def heuristic_function_1(game_state: Any, move: Any) -> object {
    return -abs((3 - move));
}
